    case 7:
      ACCEPT_TOKEN(sym_field);
      if (lookahead == '"') ADVANCE(9);
      if (lookahead == '\t' ||
          lookahead == ' ') ADVANCE(10);
      if (lookahead != 0 &&
          lookahead != '\t' &&
          lookahead != '\n' &&
          lookahead != '\r' &&
          lookahead != ',') ADVANCE(12);
      END_STATE();
    case 8:
      ACCEPT_TOKEN(sym_field);
      if (lookahead == '"') ADVANCE(2);
